-- v4.3.2 Versioned Memory Lifecycle for Oracle AI Database 26ai.
-- Facts are relational authority; native Property Graph projections consume the outbox.
DECLARE
  PROCEDURE create_table(p_name VARCHAR2, p_sql CLOB) IS BEGIN
    EXECUTE IMMEDIATE p_sql;
  EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
BEGIN
  create_table('CX_MEMORY_FAMILIES', 'CREATE TABLE CX_MEMORY_FAMILIES (FAMILY_ID VARCHAR2(128) PRIMARY KEY, LEGACY_ENTITY_ID VARCHAR2(128) UNIQUE, CURRENT_VERSION_ID VARCHAR2(128), FAMILY_STATE VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, OWNER_PRINCIPAL_ID VARCHAR2(128), WORKSPACE_ID VARCHAR2(128), SECURITY_DOMAIN_ID VARCHAR2(128), CLASSIFICATION VARCHAR2(32) DEFAULT ''INTERNAL'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, ROW_VERSION NUMBER DEFAULT 1 NOT NULL)');
  create_table('CX_MEMORY_VERSIONS', 'CREATE TABLE CX_MEMORY_VERSIONS (VERSION_ID VARCHAR2(128) PRIMARY KEY, FAMILY_ID VARCHAR2(128) NOT NULL, VERSION_NUMBER NUMBER NOT NULL, LEGACY_ENTITY_ID VARCHAR2(128), TITLE VARCHAR2(500) NOT NULL, BODY_TEXT CLOB, CONTENT_DIGEST VARCHAR2(64) NOT NULL, MEMORY_TYPE VARCHAR2(32) DEFAULT ''EPISODIC'' NOT NULL, MEMORY_SCOPE VARCHAR2(32) DEFAULT ''AGENT_MEMORY'' NOT NULL, LIFECYCLE_STATE VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, CLASSIFICATION VARCHAR2(32) DEFAULT ''INTERNAL'' NOT NULL, SOURCE_REF VARCHAR2(256), SOURCE_DIGEST VARCHAR2(64), OWNER_PRINCIPAL_ID VARCHAR2(128), OWNER_AGENT_ID VARCHAR2(128), WORKSPACE_ID VARCHAR2(128), SECURITY_DOMAIN_ID VARCHAR2(128), VALID_FROM TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, VALID_UNTIL TIMESTAMP, POLICY_VERSION VARCHAR2(64) DEFAULT ''v4.3.2'' NOT NULL, CREATED_BY VARCHAR2(128), REASON CLOB, METADATA_JSON CLOB DEFAULT ''{}'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CX_MEM_VER_FAMILY_UK UNIQUE(FAMILY_ID, VERSION_NUMBER), CONSTRAINT CX_MEM_VER_STATE_CK CHECK (LIFECYCLE_STATE IN (''CANDIDATE'',''ACTIVE'',''STALE'',''CONFLICTED'',''SUPERSEDED'',''EXPIRED'',''MIGRATED'',''ARCHIVED'',''QUARANTINED'',''UNAVAILABLE'')), CONSTRAINT CX_MEM_VER_TYPE_CK CHECK (MEMORY_TYPE IN (''EPISODIC'',''FACT'',''PREFERENCE'',''DECISION'',''PROCEDURAL'',''EXPERIENCE'')), CONSTRAINT CX_MEM_VER_SCOPE_CK CHECK (MEMORY_SCOPE IN (''RUNTIME_CONTEXT'',''CHANNEL_MEMORY'',''AGENT_MEMORY'',''WORKSPACE_MEMORY'',''ENTERPRISE_KNOWLEDGE'')))');
  create_table('CX_MEMORY_REPRESENTATIONS', 'CREATE TABLE CX_MEMORY_REPRESENTATIONS (REPRESENTATION_ID VARCHAR2(128) PRIMARY KEY, VERSION_ID VARCHAR2(128) NOT NULL, REPRESENTATION_TYPE VARCHAR2(32) NOT NULL, BODY_TEXT CLOB, CONTENT_DIGEST VARCHAR2(64) NOT NULL, TOKEN_COUNT NUMBER DEFAULT 0 NOT NULL, GENERATION_METHOD VARCHAR2(32) DEFAULT ''DETERMINISTIC'' NOT NULL, GENERATOR_VERSION VARCHAR2(128), VALIDATION_STATE VARCHAR2(24) DEFAULT ''VALID'' NOT NULL, SOURCE_VERSION_IDS_JSON CLOB DEFAULT ''[]'' NOT NULL, INDEX_STATE VARCHAR2(24) DEFAULT ''HOT'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CX_MEM_REPR_TYPE_CK CHECK (REPRESENTATION_TYPE IN (''SOURCE'',''ATOMIC_FACT'',''SHORT_SUMMARY'',''STANDARD_SUMMARY'',''TOPIC_SUMMARY'',''CHAIN_SUMMARY'')))');
  create_table('CX_MEMORY_RELATIONS', 'CREATE TABLE CX_MEMORY_RELATIONS (RELATION_ID VARCHAR2(128) PRIMARY KEY, SOURCE_VERSION_ID VARCHAR2(128) NOT NULL, TARGET_VERSION_ID VARCHAR2(128) NOT NULL, RELATION_TYPE VARCHAR2(32) NOT NULL, RELATION_STATE VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, DETERMINISTIC CHAR(1) DEFAULT ''N'' NOT NULL, CONFIDENCE NUMBER(5,4), METHOD VARCHAR2(128), EVIDENCE_JSON CLOB DEFAULT ''{}'' NOT NULL, RULE_VERSION VARCHAR2(128), CREATED_BY VARCHAR2(128), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CX_MEM_REL_DISTINCT_CK CHECK (SOURCE_VERSION_ID <> TARGET_VERSION_ID))');
  create_table('CX_MEMORY_SNAPSHOTS', 'CREATE TABLE CX_MEMORY_SNAPSHOTS (SNAPSHOT_ID VARCHAR2(128) PRIMARY KEY, RUN_ID VARCHAR2(128) NOT NULL, SNAPSHOT_VERSION NUMBER DEFAULT 1 NOT NULL, PURPOSE VARCHAR2(128) DEFAULT ''RUNTIME_CONTEXT'' NOT NULL, POLICY_VERSION VARCHAR2(64) NOT NULL, QUERY_DIGEST VARCHAR2(64) NOT NULL, SNAPSHOT_DIGEST VARCHAR2(64) NOT NULL, STATE VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, CREATED_BY VARCHAR2(128), REASON CLOB, IDEMPOTENCY_KEY VARCHAR2(128), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CX_MEM_SNAP_IDEMP_UK UNIQUE(RUN_ID, IDEMPOTENCY_KEY))');
  create_table('CX_MEMORY_SNAPSHOT_MEMBERS', 'CREATE TABLE CX_MEMORY_SNAPSHOT_MEMBERS (SNAPSHOT_ID VARCHAR2(128) NOT NULL, FAMILY_ID VARCHAR2(128) NOT NULL, VERSION_ID VARCHAR2(128) NOT NULL, REPRESENTATION_ID VARCHAR2(128), SELECTION_RANK NUMBER DEFAULT 0 NOT NULL, SELECTED_TOKENS NUMBER DEFAULT 0 NOT NULL, CONSTRAINT CX_MEM_SNAP_MEMBER_PK PRIMARY KEY(SNAPSHOT_ID, FAMILY_ID))');
  create_table('CX_MEMORY_POLICIES', 'CREATE TABLE CX_MEMORY_POLICIES (POLICY_ID VARCHAR2(128) PRIMARY KEY, POLICY_NAME VARCHAR2(128) UNIQUE NOT NULL, POLICY_VERSION VARCHAR2(64) NOT NULL, POLICY_JSON CLOB NOT NULL, STATUS VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, CREATED_BY VARCHAR2(128), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  create_table('CX_MEMORY_JOBS', 'CREATE TABLE CX_MEMORY_JOBS (JOB_ID VARCHAR2(128) PRIMARY KEY, JOB_TYPE VARCHAR2(32) NOT NULL, STATUS VARCHAR2(24) DEFAULT ''QUEUED'' NOT NULL, SCOPE_JSON CLOB DEFAULT ''{}'' NOT NULL, DRY_RUN CHAR(1) DEFAULT ''Y'' NOT NULL, POLICY_VERSION VARCHAR2(64) NOT NULL, REQUESTED_BY VARCHAR2(128), REASON CLOB, IDEMPOTENCY_KEY VARCHAR2(128) UNIQUE, LEASE_OWNER VARCHAR2(128), LEASE_EXPIRES_AT TIMESTAMP, FENCING_TOKEN NUMBER DEFAULT 0 NOT NULL, CHECKPOINT_JSON CLOB DEFAULT ''{}'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  create_table('CX_MEMORY_JOB_ITEMS', 'CREATE TABLE CX_MEMORY_JOB_ITEMS (ITEM_ID VARCHAR2(128) PRIMARY KEY, JOB_ID VARCHAR2(128) NOT NULL, SUBJECT_VERSION_ID VARCHAR2(128), STATUS VARCHAR2(24) DEFAULT ''QUEUED'' NOT NULL, ATTEMPT_COUNT NUMBER DEFAULT 0 NOT NULL, LEASE_OWNER VARCHAR2(128), LEASE_EXPIRES_AT TIMESTAMP, FENCING_TOKEN NUMBER DEFAULT 0 NOT NULL, INPUT_DIGEST VARCHAR2(64), RESULT_JSON CLOB DEFAULT ''{}'' NOT NULL, ERROR_CODE VARCHAR2(64), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  create_table('CX_MEMORY_USAGE_EVENTS', 'CREATE TABLE CX_MEMORY_USAGE_EVENTS (USAGE_EVENT_ID VARCHAR2(128) PRIMARY KEY, VERSION_ID VARCHAR2(128) NOT NULL, EVENT_TYPE VARCHAR2(32) NOT NULL, PRINCIPAL_ID VARCHAR2(128), AGENT_ID VARCHAR2(128), RUN_ID VARCHAR2(128), PURPOSE VARCHAR2(128), OUTCOME VARCHAR2(32), VALUE_NUMERIC NUMBER(12,4), IDEMPOTENCY_KEY VARCHAR2(128), METADATA_JSON CLOB DEFAULT ''{}'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CX_MEM_USAGE_IDEMP_UK UNIQUE(VERSION_ID, IDEMPOTENCY_KEY))');
  create_table('CX_MEMORY_CANDIDATES', 'CREATE TABLE CX_MEMORY_CANDIDATES (CANDIDATE_ID VARCHAR2(128) PRIMARY KEY, CANDIDATE_TYPE VARCHAR2(32) NOT NULL, SOURCE_VERSION_ID VARCHAR2(128), TARGET_VERSION_ID VARCHAR2(128), PROPOSED_JSON CLOB NOT NULL, CONFIDENCE NUMBER(5,4), STATUS VARCHAR2(24) DEFAULT ''PENDING'' NOT NULL, POLICY_RESULT VARCHAR2(24) DEFAULT ''REVIEW'' NOT NULL, CREATED_BY VARCHAR2(128), REASON CLOB, IDEMPOTENCY_KEY VARCHAR2(128) UNIQUE, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  create_table('CX_MEMORY_REVIEWS', 'CREATE TABLE CX_MEMORY_REVIEWS (REVIEW_ID VARCHAR2(128) PRIMARY KEY, CANDIDATE_ID VARCHAR2(128) NOT NULL, REVIEWER_PRINCIPAL_ID VARCHAR2(128) NOT NULL, DECISION VARCHAR2(24) NOT NULL, REASON CLOB NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  create_table('CX_MEMORY_PROJECTION_OUTBOX', 'CREATE TABLE CX_MEMORY_PROJECTION_OUTBOX (OUTBOX_ID VARCHAR2(128) PRIMARY KEY, AGGREGATE_TYPE VARCHAR2(32) NOT NULL, AGGREGATE_ID VARCHAR2(128) NOT NULL, EVENT_TYPE VARCHAR2(32) NOT NULL, PAYLOAD_JSON CLOB NOT NULL, STATUS VARCHAR2(24) DEFAULT ''PENDING'' NOT NULL, ATTEMPTS NUMBER DEFAULT 0 NOT NULL, AVAILABLE_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, LEASE_OWNER VARCHAR2(128), LEASE_EXPIRES_AT TIMESTAMP, FENCING_TOKEN NUMBER DEFAULT 0 NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, PROCESSED_AT TIMESTAMP)');
END;
/
DECLARE PROCEDURE idx(p_name VARCHAR2, p_sql VARCHAR2) IS BEGIN EXECUTE IMMEDIATE p_sql; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END; BEGIN
 idx('IDX_CX_MEM_VER_CURRENT','CREATE INDEX IDX_CX_MEM_VER_CURRENT ON CX_MEMORY_VERSIONS(FAMILY_ID,LIFECYCLE_STATE,VALID_UNTIL)');
 idx('IDX_CX_MEM_REL_SOURCE','CREATE INDEX IDX_CX_MEM_REL_SOURCE ON CX_MEMORY_RELATIONS(SOURCE_VERSION_ID,RELATION_STATE,RELATION_TYPE)');
 idx('IDX_CX_MEM_JOB_CLAIM','CREATE INDEX IDX_CX_MEM_JOB_CLAIM ON CX_MEMORY_JOBS(STATUS,LEASE_EXPIRES_AT,CREATED_AT)');
 idx('IDX_CX_MEM_OUTBOX_CLAIM','CREATE INDEX IDX_CX_MEM_OUTBOX_CLAIM ON CX_MEMORY_PROJECTION_OUTBOX(STATUS,AVAILABLE_AT,LEASE_EXPIRES_AT)');
END;
/
MERGE INTO CX_MEMORY_FAMILIES f USING (SELECT 'MF-' || TO_CHAR(ENTITY_ID) FAMILY_ID, TO_CHAR(ENTITY_ID) LEGACY_ENTITY_ID, OWNED_BY_AGENT, TO_CHAR(WORKSPACE_ID) WORKSPACE_ID FROM ENTITIES WHERE ENTITY_TYPE='MEMORY') e ON (f.LEGACY_ENTITY_ID=e.LEGACY_ENTITY_ID)
WHEN NOT MATCHED THEN INSERT(FAMILY_ID,LEGACY_ENTITY_ID,FAMILY_STATE,OWNER_PRINCIPAL_ID,WORKSPACE_ID,CLASSIFICATION) VALUES(e.FAMILY_ID,e.LEGACY_ENTITY_ID,'ACTIVE',e.OWNED_BY_AGENT,e.WORKSPACE_ID,'INTERNAL');
MERGE INTO CX_MEMORY_VERSIONS v USING (SELECT 'MV-' || TO_CHAR(ENTITY_ID) || '-1' VERSION_ID, 'MF-' || TO_CHAR(ENTITY_ID) FAMILY_ID, TO_CHAR(ENTITY_ID) LEGACY_ENTITY_ID, TITLE, CONTENT, RAWTOHEX(STANDARD_HASH(DBMS_LOB.SUBSTR(NVL(CONTENT,TO_CLOB('')),32767,1),'SHA256')) DIGEST, CASE WHEN UPPER(NVL(CATEGORY,' '))='DECISION' THEN 'DECISION' WHEN UPPER(NVL(CATEGORY,' '))='PREFERENCE' THEN 'PREFERENCE' ELSE 'EPISODIC' END MTYPE, CASE WHEN WORKSPACE_ID IS NOT NULL THEN 'WORKSPACE_MEMORY' ELSE 'AGENT_MEMORY' END MSCOPE, CASE WHEN STATUS='ACTIVE' THEN 'ACTIVE' ELSE 'STALE' END MSTATE, OWNED_BY_AGENT, TO_CHAR(WORKSPACE_ID) WORKSPACE_ID, SOURCE_AGENT FROM ENTITIES WHERE ENTITY_TYPE='MEMORY') e ON (v.FAMILY_ID=e.FAMILY_ID AND v.VERSION_NUMBER=1)
WHEN NOT MATCHED THEN INSERT(VERSION_ID,FAMILY_ID,VERSION_NUMBER,LEGACY_ENTITY_ID,TITLE,BODY_TEXT,CONTENT_DIGEST,MEMORY_TYPE,MEMORY_SCOPE,LIFECYCLE_STATE,OWNER_AGENT_ID,WORKSPACE_ID,CREATED_BY,REASON) VALUES(e.VERSION_ID,e.FAMILY_ID,1,e.LEGACY_ENTITY_ID,e.TITLE,e.CONTENT,e.DIGEST,e.MTYPE,e.MSCOPE,e.MSTATE,e.OWNED_BY_AGENT,e.WORKSPACE_ID,e.SOURCE_AGENT,'v4.3.1 adoption');
UPDATE CX_MEMORY_FAMILIES f SET CURRENT_VERSION_ID=(SELECT v.VERSION_ID FROM CX_MEMORY_VERSIONS v WHERE v.FAMILY_ID=f.FAMILY_ID AND v.VERSION_NUMBER=1), UPDATED_AT=SYSTIMESTAMP WHERE CURRENT_VERSION_ID IS NULL;
MERGE INTO CX_MEMORY_REPRESENTATIONS r USING (SELECT 'MR-' || VERSION_ID RID, VERSION_ID, BODY_TEXT, CONTENT_DIGEST FROM CX_MEMORY_VERSIONS) v ON (r.REPRESENTATION_ID=v.RID) WHEN NOT MATCHED THEN INSERT(REPRESENTATION_ID,VERSION_ID,REPRESENTATION_TYPE,BODY_TEXT,CONTENT_DIGEST,TOKEN_COUNT,SOURCE_VERSION_IDS_JSON) VALUES(v.RID,v.VERSION_ID,'SOURCE',v.BODY_TEXT,v.CONTENT_DIGEST,GREATEST(0,DBMS_LOB.GETLENGTH(NVL(v.BODY_TEXT,TO_CLOB('')))/4),'[]');
MERGE INTO CX_MEMORY_POLICIES p USING (SELECT 'MEMPOL-DEFAULT' PID FROM DUAL) d ON (p.POLICY_ID=d.PID) WHEN NOT MATCHED THEN INSERT(POLICY_ID,POLICY_NAME,POLICY_VERSION,POLICY_JSON,CREATED_BY) VALUES(d.PID,'default','v4.3.2','{"max_chain_nodes":100,"max_hops":3,"max_candidates":50,"auto_archive_days":90,"llm_enabled":false}','MIGRATION_V4_3_2');
